function jobPage(){
 const j=currentJob();if(!j)return `${button('К списку вакансий','nav','data-page="jobs"',true)}${empty('Вакансия недоступна','Возможно, публикация снята или ссылка устарела. Посмотрите другие предложения.',button('Найти работу','browse-jobs'))}`;
 const list=(heading,items)=>Array.isArray(items)&&items.length?`<section class="vacancy-section"><h2>${heading}</h2><ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></section>`:'';
 const related=state.jobs.filter(other=>other.id!==j.id&&other.status==='published'&&other.spec===j.spec).slice(0,3);
 return `<nav class="vacancy-breadcrumb" aria-label="Навигация по вакансии"><a href="#jobs" data-action="nav" data-page="jobs">Все вакансии</a><span>/</span><span>${esc(j.spec)}</span></nav><div class="vacancy-layout"><article class="vacancy-content"><header class="vacancy-header"><div class="job-company">${companyLogo(j)}<strong>${esc(j.company)}</strong>${j.own?status(j.status):''}</div><h1>${esc(j.title)}</h1><div class="vacancy-salary">${salary(j.min,j.max)} <small>в месяц${j.salaryBasis?' · '+esc(j.salaryBasis):''}</small></div><dl class="vacancy-facts"><div><dt>Опыт</dt><dd>${esc(j.experience||j.grade)}</dd></div><div><dt>Формат</dt><dd>${esc(j.format)}</dd></div><div><dt>Локация команды</dt><dd>${esc(j.city||'Россия')}</dd></div><div><dt>Занятость</dt><dd>${esc(j.employment||'Уточните у работодателя')}</dd></div>${j.schedule?`<div><dt>График</dt><dd>${esc(j.schedule)}</dd></div>`:''}</dl>${jobApplyButton(j)}${j.synthetic?'<p class="vacancy-demo-note">Пример из демонстрационного каталога. Описание и условия синтетические.</p>':''}</header><section class="vacancy-section"><h2>О работе</h2><p class="multiline">${esc(j.description)}</p>${j.team?`<p>${esc(j.team)}</p>`:''}</section>${list('Чем предстоит заниматься',j.responsibilities)}${list('Что ждём от вас',j.requirements)}${list('Будет плюсом',j.niceToHave)}<section class="vacancy-section"><h2>Технологии</h2>${tag(j.stack)}</section>${list('Что предлагаем',j.benefits)}${list('Как проходит знакомство',j.hiringSteps)}<div class="vacancy-bottom-action">${jobApplyButton(j)}<span>${j.synthetic?'Демоотклик сохранится в вашем кабинете.':'Добавьте сопроводительное письмо, если хотите рассказать о своём опыте.'}</span></div></article><aside class="vacancy-sidebar"><section class="vacancy-company-card">${companyLogo(j)}<h2>${esc(j.company)}</h2>${j.companyAbout?`<p>${esc(j.companyAbout)}</p>`:`<p>Команда в городе ${esc(j.city||'Россия')}. Подробности можно обсудить при знакомстве.</p>`}${j.companyProfile?button('О компании и команде','company-detail',`data-source="job" data-id="${esc(j.id)}"`,true):''}${j.companyWebsite&&/^https:\/\//.test(j.companyWebsite)?`<a class="text-button" href="${esc(j.companyWebsite)}" target="_blank" rel="noopener noreferrer">Сайт компании</a>`:''}<hr><div class="sidebar-vacancy-title">${esc(j.title)}</div><strong class="sidebar-vacancy-salary">${salary(j.min,j.max)}</strong>${jobApplyButton(j)}${j.synthetic?'<small>Пример из демонстрационного каталога.</small>':''}</section><section class="vacancy-profile-note">${icon('shield')}<h3>Профиль работает за вас</h3><p>Подтвердите навыки, чтобы получать прямые приглашения с открытой зарплатой.</p>${button('Моё резюме','join','data-role="candidate" href="#profile"',true)}</section></aside></div>${related.length?`<section class="related-vacancies"><div class="section-heading"><h2>Ещё в направлении ${esc(j.spec)}</h2></div><div class="job-grid">${related.map(jobCard).join('')}</div></section>`:''}`;
}
let motionObserver;
function animateView(){
 if(typeof IntersectionObserver==='undefined'||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;
 motionObserver?.disconnect();motionObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){entry.target.dataset.motion='visible';motionObserver.unobserve(entry.target);}}},{threshold:0.08});
 document.querySelectorAll('.home-vacancy,.specialization-grid>button,.reverse-flow li').forEach((card,i)=>{card.dataset.motion='pending';card.style.setProperty('--motion-delay',`${Math.min(i%5,3)*45}ms`);motionObserver.observe(card);});
}
